% Revision convention: red = retained deleted text; green = inserted text.
% Define \ReviewClean before inputting this file to accept the changes.
\definecolor{revisionred}{RGB}{190,0,0}
\definecolor{revisiongreen}{RGB}{0,115,35}
\newif\ifreviewmarkup
\ifdefined\ReviewClean\reviewmarkupfalse\else\reviewmarkuptrue\fi
\DeclareRobustCommand{\revdel}[1]{\ifreviewmarkup{\color{revisionred}\hypersetup{linkcolor=revisionred,citecolor=revisionred}#1}\fi}
\DeclareRobustCommand{\revadd}[1]{{\ifreviewmarkup\color{revisiongreen}\hypersetup{linkcolor=revisiongreen,citecolor=revisiongreen}\fi#1}}
\newcommand{\revfigure}[1]{\ifreviewmarkup\includegraphics[width=0.9\textwidth]{figs/#1}\else\includegraphics[width=0.9\textwidth]{figs_clean/#1}\fi}
\DeclareUnicodeCharacter{2011}{-}

\usepackage{etoolbox}
\AtBeginDocument{%
  \let\revieworiginalbibitem\bibitem
  \renewcommand{\bibitem}[2][]{%
    \ifreviewmarkup
      \ifstrequal{#2}{liuTorusEventBased2025}{\color{revisiongreen}}{%
        \ifstrequal{#2}{chandrasekarAdaptiveEvent2026}{\color{revisiongreen}}{\normalcolor}}%
    \fi
    \revieworiginalbibitem[#1]{#2}}
}
